args.sql:
SELECT tx_key, cur_med, med_side, 
       CASE WHEN cur_med = 'None' THEN 0 ELSE cardinality(string_to_array(cur_med, ',')) END as med_count
FROM treatmentbasics LIMIT 10;

SELECT ab_key, pat_owner_ref, med_side_eff_density,
       REGEXP_REPLACE(med_side_eff_density, '[^0-9.]', '')::numeric as density_numeric
FROM assessmentbasics LIMIT 10;

SELECT ab_key, pat_owner_ref, med_side_eff_density,
       SPLIT_PART(med_side_eff_density, ' ', 1)::numeric as density_numeric
FROM assessmentbasics LIMIT 10;

SELECT DISTINCT enc.pat_ref
FROM encounters enc
WHERE enc.fac_id = 'F533';
